#include <shared_mutex>
#include <chrono>
#include <iostream>
#include <thread>

int main() {
    std::shared_timed_mutex mtx;  // Expert note: This allocates memory for atomic state variables, typically 8-16 bytes on 64-bit systems, aligned for cache efficiency.
    auto start = std::chrono::steady_clock::now();
    bool locked = mtx.try_lock_shared_for(std::chrono::seconds(1));  // Attempts shared lock with 1-second timeout; compiler may optimize this into a loop with atomic CAS instructions.
    auto end = std::chrono::steady_clock::now();
    if (locked) {
        std::cout << "Shared lock acquired successfully." << std::endl;  // If successful, the atomic operation succeeded without waiting.
        mtx.unlock_shared();  // Releases the shared lock, decrementing the atomic counter.
    } else {
        std::cout << "Failed to acquire shared lock within timeout." << std::endl;  // Timeout occurred; the function returned false after runtime checks.
    }
    std::cout << "Operation took: " << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ms" << std::endl;
    return 0;
}
